@Test
public void practice_buildSearchPathList_searchPath() {
    BST<Integer> bst = new BST<>();
    bst.add(77); bst.add(37); bst.add(93); bst.add(35); bst.add(52);
    assertEquals("[77, 37, 52]", bst.buildSearchPathList(52).toString());
    assertEquals("[77, 37, 35]", bst.buildSearchPathList(35).toString());
    assertEquals("[77]",         bst.buildSearchPathList(77).toString());
    assertEquals("[]",           bst.buildSearchPathList(99).toString());
    points += 1;
}

@Test
public void practice_countSiblingDiffGreaterThan_basicCases() {
    BST<Integer> bst = new BST<>();
    assertEquals(0, bst.countSiblingDiffGreaterThan(8));
    bst.add(20); bst.add(15); bst.add(25);
    assertEquals(1, bst.countSiblingDiffGreaterThan(8));  // 25-15=10 > 8
    assertEquals(0, bst.countSiblingDiffGreaterThan(12)); // 25-15=10 not > 12
    bst.add(10); bst.add(30);
    assertEquals(2, bst.countSiblingDiffGreaterThan(8));  // also 30-10=20 > 8
    points += 1;
}

@Test
public void practice_weightedHeight_sevenNodeExample() {
    BST<Integer> bst = new BST<>();
    // Build: e=root(size 7, height 3), b(size 4, height 2), h(size 2, height 1)
    //        a(size 1,h0), c(size 2,h1), g(size 1,h0)
    //        d(size 1,h0), f(size 1,h0)
    // weightedHeight = 3*7 + 2*4 + 1*2 + 0*1 + 1*2 + 0*1 + 0*1 + 0*1 = 21+8+2+2 = ... check with simpler tree
    bst.add(10); bst.add(5); bst.add(15);
    // root h=1,s=3 → 3; left h=0,s=1 → 0; right h=0,s=1 → 0
    assertEquals(3, bst.weightedHeight());
    bst.add(3);
    // root h=2,s=4 → 8; left h=1,s=2 → 2; left.left h=0,s=1 → 0; right h=0,s=1 → 0
    assertEquals(10, bst.weightedHeight());
    points += 1;
}

@Test
public void practice_pruneLeaves_repeatedPruning() {
    BST<Integer> bst = new BST<>();
    bst.add(10); bst.add(5); bst.add(15); bst.add(3);
    bst.pruneLeaves();
    assertEquals("[5, 10, 15]", bst.toString());
    bst.pruneLeaves();
    assertEquals("[10]", bst.toString());
    bst.pruneLeaves();
    assertEquals("[]", bst.toString());
    points += 1;
}

@Test
public void practice_branchPoint_basicCases() {
    BST<Integer> bst = new BST<>();
    bst.add(50); bst.add(25); bst.add(75); bst.add(12); bst.add(37);
    // search paths for 12 and 37 diverge at 25
    assertEquals(Integer.valueOf(25), bst.branchPoint(12, 37));
    // search paths for 12 and 75 diverge at 50 (root)
    assertEquals(Integer.valueOf(50), bst.branchPoint(12, 75));
    // search paths for 12 and 25 diverge at 25 (25 is ancestor of 12)
    assertEquals(Integer.valueOf(25), bst.branchPoint(12, 25));
    points += 1;
}

@Test
public void practice_countOneChildParents_mixedTree() {
    BST<Integer> bst = new BST<>();
    assertEquals(0, bst.countOneChildParents());
    bst.add(50); bst.add(25); bst.add(75); bst.add(12);
    // 25 has only left child (12); 50 and 75 have 0 or 2 children
    assertEquals(1, bst.countOneChildParents());
    bst.add(37);
    // now 25 has two children — no longer counts
    assertEquals(0, bst.countOneChildParents());
    points += 1;
}

